export const SPEECH_INDEX_113C = SPEECH_ENTRIES_113C;
export const SPEECH_BY_ID_113C = SPEECH_ENTRIES_113C;
export const SPEECH_STREAMS_113C = SPEECH_ENTRIES_113C;
export const SPEECH_TABLE_113C = SPEECH_ENTRIES_113C;

const SPEECH_BY_SOUND_MAP = new Map<string, SpeechEntry113c>();
for (const entry of Object.values(SPEECH_ENTRIES_113C)) {
  SPEECH_BY_SOUND_MAP.set(entry.sound.toLowerCase(), entry);
}

export function resolveSpeechEntry113c(idOrName: number | string): SpeechEntry113c | undefined {
  if (typeof idOrName === 'number') {
    return SPEECH_ENTRIES_113C[idOrName];
  }
  const trimmed = String(idOrName).trim().toLowerCase();
  if (!trimmed) return undefined;
  const asNum = Number(trimmed);
  if (Number.isInteger(asNum) && SPEECH_ENTRIES_113C[asNum]) {
    return SPEECH_ENTRIES_113C[asNum];
  }
  return SPEECH_BY_SOUND_MAP.get(trimmed);
}

export const getSpeechEntry113c = resolveSpeechEntry113c;

export function getSpeechUrl113c(idOrName: number | string): string | undefined {
  return resolveSpeechEntry113c(idOrName)?.url;
}
export const resolveSpeechUrl113c = getSpeechUrl113c;
